		if (incident?.duration) {
			details.push(`Incident duration: ${incident.duration}`);
		}

		if (decision.isEscalation && decision.escalationMinutes) {
			details.push(`Escalation trigger: ${decision.escalationMinutes} minute(s)`);
		}

